private final ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();
private final Lock r = rwl.readLock(), w = rwl.writeLock();
private final Map<String, Data> cache = new TreeMap<>();

Data get(String key) {
    r.lock();
    try { return cache.get(key); } finally { r.unlock(); }
}

void put(String key, Data v) {
    w.lock();
    try { cache.put(key, v); } finally { w.unlock(); }
}

